const amqp = require('amqplib');
const url = "amqp://guest:guest@localhost:5672";
const queues = ["cache.invalidate","document.embed","chat.document.embed","evidence.process","vector.index","chat.context","analytics.track","codebase.index","ace.evaluate","error.embed","synthesis.generate","knowledge.backfill","audio.process","glyph.tile.rebuild","qlora.distill","media.download","media.transcribe","cards.refresh","repair.workflow.run","inference.log.flush"];
(async () => {
  const conn = await amqp.connect(url);
  const ch = await conn.createChannel();
  const out = [];
  for (const name of queues) {
    try {
      const info = await ch.checkQueue(name);
      out.push({ name, messages: info.messageCount, consumers: info.consumerCount, status: 'READY' });
    } catch (error) {
      out.push({ name, messages: null, consumers: null, status: 'MISSING', error: error.message });
    }
  }
  await ch.close();
  await conn.close();
  console.log(JSON.stringify(out));
})().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
